begin;
create extension if not exists pgcrypto;

create type public.app_role as enum ('admin','warehouse_manager','warehouse_staff','viewer');
create type public.document_status as enum ('draft','confirmed','cancelled');
create type public.movement_kind as enum ('receipt','issue','adjustment','reversal');

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null check (length(trim(display_name)) between 1 and 120),
  role public.app_role not null default 'viewer', is_active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.categories (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null unique, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.suppliers (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, contact_note text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.warehouses (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, location_note text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products (
  id uuid primary key default gen_random_uuid(), sku text not null unique, name text not null,
  category_id uuid not null references public.categories(id) on delete restrict,
  unit text not null, barcode text unique, reference_cost numeric(16,2) not null default 0 check(reference_cost>=0), reference_price numeric(16,2) not null default 0 check(reference_price>=0),
  minimum_stock numeric(14,3) not null default 0 check(minimum_stock>=0), tracks_batches boolean not null default false, is_active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.product_suppliers (product_id uuid not null references public.products(id) on delete restrict, supplier_id uuid not null references public.suppliers(id) on delete restrict, is_default boolean not null default false, created_at timestamptz not null default now(), primary key(product_id,supplier_id));
create unique index product_one_default_supplier on public.product_suppliers(product_id) where is_default;
create table public.product_batches (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete restrict, batch_code text not null, manufactured_on date, expires_on date, created_at timestamptz not null default now(), unique(product_id,batch_code), check(expires_on is null or manufactured_on is null or expires_on>=manufactured_on));
create table public.inventory_balances (id uuid primary key default gen_random_uuid(), warehouse_id uuid not null references public.warehouses(id) on delete restrict, product_id uuid not null references public.products(id) on delete restrict, batch_id uuid references public.product_batches(id) on delete restrict, quantity numeric(14,3) not null default 0 check(quantity>=0), updated_at timestamptz not null default now());
create unique index inventory_balance_key on public.inventory_balances(warehouse_id,product_id,batch_id) nulls not distinct;

create table public.stock_receipts (id uuid primary key default gen_random_uuid(), code text not null unique, warehouse_id uuid not null references public.warehouses(id) on delete restrict, supplier_id uuid references public.suppliers(id) on delete restrict, occurred_at timestamptz not null default now(), status public.document_status not null default 'draft', note text, created_by uuid not null references public.profiles(id) on delete restrict, confirmed_by uuid references public.profiles(id) on delete restrict, confirmed_at timestamptz, cancelled_by uuid references public.profiles(id) on delete restrict, cancelled_at timestamptz, cancellation_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.stock_receipt_items (id uuid primary key default gen_random_uuid(), receipt_id uuid not null references public.stock_receipts(id) on delete cascade, product_id uuid not null references public.products(id) on delete restrict, batch_id uuid references public.product_batches(id) on delete restrict, quantity numeric(14,3) not null check(quantity>0), unit_cost numeric(16,2) not null check(unit_cost>=0), created_at timestamptz not null default now(), unique nulls not distinct(receipt_id,product_id,batch_id));
create table public.stock_issues (id uuid primary key default gen_random_uuid(), code text not null unique, warehouse_id uuid not null references public.warehouses(id) on delete restrict, occurred_at timestamptz not null default now(), reason text not null check(length(trim(reason))>0), status public.document_status not null default 'draft', note text, created_by uuid not null references public.profiles(id) on delete restrict, confirmed_by uuid references public.profiles(id) on delete restrict, confirmed_at timestamptz, cancelled_by uuid references public.profiles(id) on delete restrict, cancelled_at timestamptz, cancellation_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.stock_issue_items (id uuid primary key default gen_random_uuid(), issue_id uuid not null references public.stock_issues(id) on delete cascade, product_id uuid not null references public.products(id) on delete restrict, batch_id uuid references public.product_batches(id) on delete restrict, quantity numeric(14,3) not null check(quantity>0), created_at timestamptz not null default now(), unique nulls not distinct(issue_id,product_id,batch_id));
create table public.stock_adjustments (id uuid primary key default gen_random_uuid(), code text not null unique, warehouse_id uuid not null references public.warehouses(id) on delete restrict, occurred_at timestamptz not null default now(), reason text not null check(length(trim(reason))>0), status public.document_status not null default 'draft', note text, created_by uuid not null references public.profiles(id) on delete restrict, confirmed_by uuid references public.profiles(id) on delete restrict, confirmed_at timestamptz, cancelled_by uuid references public.profiles(id) on delete restrict, cancelled_at timestamptz, cancellation_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.stock_adjustment_items (id uuid primary key default gen_random_uuid(), adjustment_id uuid not null references public.stock_adjustments(id) on delete cascade, product_id uuid not null references public.products(id) on delete restrict, batch_id uuid references public.product_batches(id) on delete restrict, counted_quantity numeric(14,3) not null check(counted_quantity>=0), book_quantity numeric(14,3), created_at timestamptz not null default now(), unique nulls not distinct(adjustment_id,product_id,batch_id));
create table public.stock_movements (id uuid primary key default gen_random_uuid(), movement_kind public.movement_kind not null, warehouse_id uuid not null references public.warehouses(id) on delete restrict, product_id uuid not null references public.products(id) on delete restrict, batch_id uuid references public.product_batches(id) on delete restrict, quantity_delta numeric(14,3) not null check(quantity_delta<>0), quantity_before numeric(14,3) not null check(quantity_before>=0), quantity_after numeric(14,3) not null check(quantity_after>=0), reference_unit_cost numeric(16,2), source_type text not null check(source_type in ('receipt','issue','adjustment')), source_id uuid not null, source_item_id uuid not null, reversed_movement_id uuid references public.stock_movements(id) on delete restrict, actor_id uuid not null references public.profiles(id) on delete restrict, reason text, occurred_at timestamptz not null, created_at timestamptz not null default now(), unique(source_type,source_id,source_item_id,movement_kind));
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id) on delete restrict, action text not null, entity_type text not null, entity_id uuid, details jsonb not null default '{}', created_at timestamptz not null default now());

create index products_category_idx on public.products(category_id); create index balances_lookup_idx on public.inventory_balances(warehouse_id,product_id); create index batches_expiry_idx on public.product_batches(expires_on) where expires_on is not null; create index movements_time_idx on public.stock_movements(occurred_at desc); create index movements_product_idx on public.stock_movements(product_id,warehouse_id,occurred_at desc); create index receipts_status_time_idx on public.stock_receipts(status,occurred_at desc); create index issues_status_time_idx on public.stock_issues(status,occurred_at desc);

create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['profiles','categories','suppliers','warehouses','products','inventory_balances','stock_receipts','stock_issues','stock_adjustments'] loop execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t); end loop; end $$;
create function public.current_role() returns public.app_role language sql stable security definer set search_path='' as $$ select role from public.profiles where id=auth.uid() and is_active $$;
create function public.is_active_user() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and is_active) $$;
create function public.is_manager() returns boolean language sql stable security definer set search_path='' as $$ select coalesce(public.current_role() in ('admin','warehouse_manager'),false) $$;
create function public.guard_movement_immutable() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'Stock movements are immutable'; end $$;
create trigger stock_movements_immutable before update or delete on public.stock_movements for each row execute function public.guard_movement_immutable();

create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),split_part(coalesce(new.email,'Người dùng'),'@',1))); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

create function public.ensure_balance(p_warehouse uuid,p_product uuid,p_batch uuid) returns public.inventory_balances language plpgsql security definer set search_path='' as $$ declare b public.inventory_balances; begin
 insert into public.inventory_balances(warehouse_id,product_id,batch_id,quantity) values(p_warehouse,p_product,p_batch,0) on conflict (warehouse_id,product_id,batch_id) do nothing;
 select * into b from public.inventory_balances where warehouse_id=p_warehouse and product_id=p_product and batch_id is not distinct from p_batch for update; return b; end $$;

create function public.confirm_stock_receipt(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare d public.stock_receipts; i public.stock_receipt_items; b public.inventory_balances; begin
 if not public.is_manager() then raise exception 'Bạn không có quyền xác nhận phiếu'; end if;
 select * into d from public.stock_receipts where id=p_id for update; if not found then raise exception 'Không tìm thấy phiếu nhập'; end if; if d.status<>'draft' then raise exception 'Phiếu không còn ở trạng thái nháp'; end if; if not exists(select 1 from public.stock_receipt_items where receipt_id=p_id) then raise exception 'Phiếu nhập chưa có dòng hàng'; end if;
 for i in select * from public.stock_receipt_items where receipt_id=p_id order by product_id,batch_id loop b:=public.ensure_balance(d.warehouse_id,i.product_id,i.batch_id); update public.inventory_balances set quantity=b.quantity+i.quantity where id=b.id; insert into public.stock_movements(movement_kind,warehouse_id,product_id,batch_id,quantity_delta,quantity_before,quantity_after,reference_unit_cost,source_type,source_id,source_item_id,actor_id,occurred_at) values('receipt',d.warehouse_id,i.product_id,i.batch_id,i.quantity,b.quantity,b.quantity+i.quantity,i.unit_cost,'receipt',d.id,i.id,auth.uid(),d.occurred_at); end loop;
 update public.stock_receipts set status='confirmed',confirmed_by=auth.uid(),confirmed_at=now() where id=p_id; end $$;

create function public.confirm_stock_issue(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare d public.stock_issues; i public.stock_issue_items; b public.inventory_balances; begin
 if not public.is_manager() then raise exception 'Bạn không có quyền xác nhận phiếu'; end if;
 select * into d from public.stock_issues where id=p_id for update; if not found then raise exception 'Không tìm thấy phiếu xuất'; end if; if d.status<>'draft' then raise exception 'Phiếu không còn ở trạng thái nháp'; end if; if not exists(select 1 from public.stock_issue_items where issue_id=p_id) then raise exception 'Phiếu xuất chưa có dòng hàng'; end if;
 for i in select * from public.stock_issue_items where issue_id=p_id order by product_id,batch_id loop b:=public.ensure_balance(d.warehouse_id,i.product_id,i.batch_id); if b.quantity<i.quantity then raise exception 'Tồn kho không đủ cho sản phẩm %',i.product_id; end if; update public.inventory_balances set quantity=b.quantity-i.quantity where id=b.id; insert into public.stock_movements(movement_kind,warehouse_id,product_id,batch_id,quantity_delta,quantity_before,quantity_after,source_type,source_id,source_item_id,actor_id,reason,occurred_at) values('issue',d.warehouse_id,i.product_id,i.batch_id,-i.quantity,b.quantity,b.quantity-i.quantity,'issue',d.id,i.id,auth.uid(),d.reason,d.occurred_at); end loop;
 update public.stock_issues set status='confirmed',confirmed_by=auth.uid(),confirmed_at=now() where id=p_id; end $$;

create function public.confirm_stock_adjustment(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare d public.stock_adjustments; i public.stock_adjustment_items; b public.inventory_balances; delta numeric(14,3); begin
 if not public.is_manager() then raise exception 'Bạn không có quyền điều chỉnh tồn'; end if;
 select * into d from public.stock_adjustments where id=p_id for update; if not found then raise exception 'Không tìm thấy phiếu điều chỉnh'; end if; if d.status<>'draft' then raise exception 'Phiếu không còn ở trạng thái nháp'; end if; if not exists(select 1 from public.stock_adjustment_items where adjustment_id=p_id) then raise exception 'Phiếu chưa có dòng hàng'; end if;
 for i in select * from public.stock_adjustment_items where adjustment_id=p_id order by product_id,batch_id loop b:=public.ensure_balance(d.warehouse_id,i.product_id,i.batch_id); delta:=i.counted_quantity-b.quantity; if delta=0 then raise exception 'Số kiểm đếm không tạo chênh lệch'; end if; update public.stock_adjustment_items set book_quantity=b.quantity where id=i.id; update public.inventory_balances set quantity=i.counted_quantity where id=b.id; insert into public.stock_movements(movement_kind,warehouse_id,product_id,batch_id,quantity_delta,quantity_before,quantity_after,source_type,source_id,source_item_id,actor_id,reason,occurred_at) values('adjustment',d.warehouse_id,i.product_id,i.batch_id,delta,b.quantity,i.counted_quantity,'adjustment',d.id,i.id,auth.uid(),d.reason,d.occurred_at); end loop;
 update public.stock_adjustments set status='confirmed',confirmed_by=auth.uid(),confirmed_at=now() where id=p_id; end $$;

create function public.cancel_stock_document(p_type text,p_id uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$ declare m public.stock_movements; b public.inventory_balances; s public.document_status; begin
 if not public.is_manager() then raise exception 'Bạn không có quyền đảo phiếu'; end if; if p_type not in ('receipt','issue','adjustment') or length(trim(coalesce(p_reason,'')))=0 then raise exception 'Loại phiếu hoặc lý do không hợp lệ'; end if;
 execute format('select status from public.stock_%s%s where id=$1 for update',case when p_type='receipt' then 'receipt' when p_type='issue' then 'issue' else 'adjustment' end,case when p_type in ('receipt','issue') then 's' else 's' end) into s using p_id;
 if s is null then raise exception 'Không tìm thấy phiếu'; end if; if s<>'confirmed' then raise exception 'Chỉ có thể đảo phiếu đã xác nhận'; end if;
 for m in select * from public.stock_movements where source_type=p_type and source_id=p_id and movement_kind<>'reversal' order by product_id,batch_id for update loop b:=public.ensure_balance(m.warehouse_id,m.product_id,m.batch_id); if b.quantity-m.quantity_delta<0 then raise exception 'Không thể đảo vì sẽ làm tồn âm'; end if; update public.inventory_balances set quantity=b.quantity-m.quantity_delta where id=b.id; insert into public.stock_movements(movement_kind,warehouse_id,product_id,batch_id,quantity_delta,quantity_before,quantity_after,reference_unit_cost,source_type,source_id,source_item_id,reversed_movement_id,actor_id,reason,occurred_at) values('reversal',m.warehouse_id,m.product_id,m.batch_id,-m.quantity_delta,b.quantity,b.quantity-m.quantity_delta,m.reference_unit_cost,p_type,p_id,m.source_item_id,m.id,auth.uid(),p_reason,now()); end loop;
 execute format('update public.stock_%s set status=''cancelled'',cancelled_by=$1,cancelled_at=now(),cancellation_reason=$2 where id=$3',case when p_type='receipt' then 'receipts' when p_type='issue' then 'issues' else 'adjustments' end) using auth.uid(),p_reason,p_id;
end $$;

do $$ declare t text; begin foreach t in array array['profiles','categories','suppliers','warehouses','products','product_suppliers','product_batches','inventory_balances','stock_receipts','stock_receipt_items','stock_issues','stock_issue_items','stock_adjustments','stock_adjustment_items','stock_movements','audit_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for select to authenticated using (public.is_active_user())','read_'||t,t); end loop; end $$;
create policy admin_profiles_update on public.profiles for update to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');
do $$ declare t text; begin foreach t in array array['categories','suppliers','warehouses','products','product_suppliers','product_batches'] loop execute format('create policy %I on public.%I for all to authenticated using (public.is_manager()) with check (public.is_manager())','manage_'||t,t); end loop; end $$;
create policy receipt_insert on public.stock_receipts for insert to authenticated with check(public.current_role() in ('admin','warehouse_manager','warehouse_staff') and created_by=auth.uid() and status='draft');
create policy issue_insert on public.stock_issues for insert to authenticated with check(public.current_role() in ('admin','warehouse_manager','warehouse_staff') and created_by=auth.uid() and status='draft');
create policy adjustment_insert on public.stock_adjustments for insert to authenticated with check(public.is_manager() and created_by=auth.uid() and status='draft');
create policy receipt_draft_update on public.stock_receipts for update to authenticated using(status='draft' and (created_by=auth.uid() or public.is_manager())) with check(status='draft');
create policy issue_draft_update on public.stock_issues for update to authenticated using(status='draft' and (created_by=auth.uid() or public.is_manager())) with check(status='draft');
create policy adjustment_draft_update on public.stock_adjustments for update to authenticated using(status='draft' and public.is_manager()) with check(status='draft');
create policy receipt_item_write on public.stock_receipt_items for all to authenticated using(exists(select 1 from public.stock_receipts d where d.id=receipt_id and d.status='draft' and (d.created_by=auth.uid() or public.is_manager()))) with check(exists(select 1 from public.stock_receipts d where d.id=receipt_id and d.status='draft' and (d.created_by=auth.uid() or public.is_manager())));
create policy issue_item_write on public.stock_issue_items for all to authenticated using(exists(select 1 from public.stock_issues d where d.id=issue_id and d.status='draft' and (d.created_by=auth.uid() or public.is_manager()))) with check(exists(select 1 from public.stock_issues d where d.id=issue_id and d.status='draft' and (d.created_by=auth.uid() or public.is_manager())));
create policy adjustment_item_write on public.stock_adjustment_items for all to authenticated using(exists(select 1 from public.stock_adjustments d where d.id=adjustment_id and d.status='draft' and public.is_manager())) with check(exists(select 1 from public.stock_adjustments d where d.id=adjustment_id and d.status='draft' and public.is_manager()));

revoke all on all tables in schema public from anon,authenticated; grant select on all tables in schema public to authenticated; grant insert,update,delete on public.categories,public.suppliers,public.warehouses,public.products,public.product_suppliers,public.product_batches,public.stock_receipts,public.stock_receipt_items,public.stock_issues,public.stock_issue_items,public.stock_adjustments,public.stock_adjustment_items to authenticated; grant update on public.profiles to authenticated;
revoke all on function public.ensure_balance(uuid,uuid,uuid) from public,anon,authenticated; revoke all on function public.confirm_stock_receipt(uuid) from public,anon; revoke all on function public.confirm_stock_issue(uuid) from public,anon; revoke all on function public.confirm_stock_adjustment(uuid) from public,anon; revoke all on function public.cancel_stock_document(text,uuid,text) from public,anon; grant execute on function public.confirm_stock_receipt(uuid),public.confirm_stock_issue(uuid),public.confirm_stock_adjustment(uuid),public.cancel_stock_document(text,uuid,text) to authenticated;
commit;
